INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Programm immer den gesamten Code zuerst übersetzt?', 2, '[{"text": "Nein", "correct": true, "because": "Zeile für Zeile ausführbar"}, {"text": "Ja", "correct": false, "because": "Nicht bei Interpreter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal unterscheidet ein Ausführungstool von einem Compiler?', 3, '[{"text": "Zeilenweise Ausführung", "correct": true, "because": "Kein vollständiger Build"}, {"text": "Maschinencode", "correct": false, "because": "Compiler macht das"}, {"text": "Schnellere Laufzeit", "correct": false, "because": "Abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Tool zur direkten Codeausführung?', 5, '[{"text": "Interaktivität", "correct": true, "because": "Direkte Rückmeldung"}, {"text": "Zeilenweise Verarbeitung", "correct": true, "because": "Kein Vorab-Build"}, {"text": "Fehlererkennung", "correct": true, "because": "Laufzeitfehler sichtbar"}, {"text": "Maschinencode", "correct": false, "because": "Compiler-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es führt Code direkt aus. b) Es erzeugt eine ausführbare Datei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Compiler"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Tool zur Codeausführung nutze?', 4, '[{"text": "Laufzeitfehler", "correct": false, "because": "Wichtig zu prüfen"}, {"text": "Interaktivität", "correct": false, "because": "Kernfunktion"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein solches Tool immer langsamer als ein Compiler ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Einsatz"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein Tool, das Code zeilenweise ausführt?', 3, '[{"text": "Python", "correct": true, "because": "Interpretiert direkt"}, {"text": "C++", "correct": false, "because": "Compiliert"}, {"text": "Java", "correct": false, "because": "Bytecode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Tool zur direkten Ausführung?', 5, '[{"text": "Schnelle Tests", "correct": true, "because": "Sofortige Rückmeldung"}, {"text": "Flexibilität", "correct": true, "because": "Kein Build nötig"}, {"text": "Einfache Fehlererkennung", "correct": true, "because": "Laufzeit sichtbar"}, {"text": "Maschinencode", "correct": false, "because": "Compiler-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Python ein solches Tool nutzt und b) es immer kompiliert wird. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Code zeilenweise auszuführen?', 4, '[{"text": "Laufzeitumgebung", "correct": false, "because": "Notwendig"}, {"text": "Quellcode", "correct": false, "because": "Basis der Ausführung"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Ausführungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erzeugt ein solches Tool eine EXE-Datei?', 2, '[{"text": "Nein", "correct": true, "because": "Direkte Ausführung"}, {"text": "Ja", "correct": false, "because": "Compiler-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Tool zur direkten Ausführung?', 4, '[{"text": "Langsamere Laufzeit", "correct": true, "because": "Keine Optimierung"}, {"text": "Fehler bei Laufzeit", "correct": true, "because": "Keine Vorprüfung"}, {"text": "Hohe Komplexität", "correct": false, "because": "Einfacher"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es nur für kleine Programme geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch große Projekte"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Tool, das Code direkt ausführt?', 3, '[{"text": "Schnelles Testen", "correct": true, "because": "Sofortige Rückmeldung"}, {"text": "Maschinencode", "correct": false, "because": "Compiler-Ziel"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es prüft Code bei Ausführung. b) Es optimiert vorab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Compiler"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Laufzeitumgebung?', 4, '[{"text": "Code ausführen", "correct": true, "because": "Ermöglicht Interpretation"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}, {"text": "Design anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein solches Tool vorab prüft?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Laufzeit"}, {"text": "Ja", "correct": false, "because": "Compiler-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Ausführungstool nützlich?', 5, '[{"text": "Interaktivität", "correct": true, "because": "Direkte Tests"}, {"text": "Einfachheit", "correct": true, "because": "Kein Build nötig"}, {"text": "Fehlererkennung", "correct": true, "because": "Laufzeit sichtbar"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Python ein Beispiel dafür?', 3, '[{"text": "Ja", "correct": true, "because": "Interpretiert Code"}, {"text": "Nein", "correct": false, "because": "Typisches Beispiel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Tool zur direkten Ausführung?', 4, '[{"text": "Interaktives Skript testen", "correct": true, "because": "Sofortige Rückmeldung"}, {"text": "Maschinencode erstellen", "correct": false, "because": "Compiler"}, {"text": "Datenbankdesign", "correct": false, "because": "Anderer Zweck"}]');
